```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

struct Node;

impl Guest for Node {
    fn run(reply: AgentResponse) -> DeliveryConfirmation {
        let confirmation = crate::aap::caps::response_channel::send(&reply.text);
        // The contract requires delivered == true and a present session id.
        // The host stamps both; if it ever does not, trap rather than emit
        // an output that violates the contract.
        assert!(confirmation.delivered, "response channel did not deliver");
        assert!(!confirmation.session.is_empty(), "missing session id");
        confirmation
    }
}

export!(Node);
